PER_GB = {'FP32': 4, 'FP16': 2, 'BF16': 2, 'INT8': 1, 'INT4': 0.5}


def infer_gb(params_b, precision):
    if precision not in PER_GB:
        raise ValueError('unknown precision: ' + precision)
    return params_b * PER_GB[precision]


def train_gb(params_b, precision, mode):
    if precision not in PER_GB:
        raise ValueError('unknown precision: ' + precision)
    if mode == 'full':
        return params_b * 16
    if mode == 'lora':
        return params_b * (PER_GB[precision] + 0.5)
    raise ValueError('unknown mode: ' + mode)

print(infer_gb(7, 'FP16'), train_gb(7, 'FP16', 'full'))
